blocks.body:
{
    "level": "B2–C1",
    "intro": "У цій темі ти детально вивчиш <strong>пасивний герундій<\/strong>: як утворювати простий (being done) та перфектний (having been done) пасивний герундій, коли їх використовувати та після яких слів вони вживаються.",
    "rules": [
        {
            "label": "Простий",
            "color": "emerald",
            "text": "<strong>being + V3 (Past Participle)<\/strong> — одночасна дія:",
            "example": "She hates being interrupted."
        },
        {
            "label": "Перфектний",
            "color": "blue",
            "text": "<strong>having been + V3<\/strong> — попередня дія:",
            "example": "Having been warned, he was careful."
        },
        {
            "label": "Порівняння",
            "color": "rose",
            "text": "Active: <strong>doing \/ having done<\/strong> → Passive: <strong>being done \/ having been done<\/strong>",
            "example": "writing → being written → having been written"
        }
    ]
}

{
    "title": "1. Утворення пасивного герундія",
    "intro": "Порівняння активних та пасивних форм герундія:",
    "items": [
        {
            "label": "Active Simple",
            "title": "doing \/ writing",
            "subtitle": "I enjoy writing letters. — Мені подобається писати листи."
        },
        {
            "label": "Passive Simple",
            "title": "being done \/ being written",
            "subtitle": "He dislikes being criticized. — Йому не подобається, коли його критикують."
        },
        {
            "label": "Active Perfect",
            "title": "having done \/ having written",
            "subtitle": "Having finished the work, she left. — Закінчивши роботу, вона пішла."
        },
        {
            "label": "Passive Perfect",
            "title": "having been done \/ having been written",
            "subtitle": "Having been rejected, she tried again. — Отримавши відмову, вона спробувала знову."
        }
    ]
}

{
    "title": "2. Простий пасивний герундій (being done)",
    "sections": [
        {
            "label": "Після дієслів почуттів",
            "color": "emerald",
            "description": "Після <strong>like, hate, enjoy, love, dislike, avoid, mind<\/strong>:",
            "examples": [
                {
                    "en": "She hates being interrupted.",
                    "ua": "Вона ненавидить, коли її перебивають."
                },
                {
                    "en": "Nobody likes being criticized.",
                    "ua": "Ніхто не любить, коли його критикують."
                },
                {
                    "en": "He enjoys being praised.",
                    "ua": "Йому подобається, коли його хвалять."
                },
                {
                    "en": "I don't mind being asked questions.",
                    "ua": "Я не проти, коли мені ставлять запитання."
                }
            ]
        },
        {
            "label": "Після прийменників",
            "color": "blue",
            "description": "Після <strong>without, after, before, despite, instead of, on<\/strong>:",
            "examples": [
                {
                    "en": "He left without being noticed.",
                    "ua": "Він пішов непомітно."
                },
                {
                    "en": "After being rejected, she applied again.",
                    "ua": "Після відмови вона подала заявку знову."
                },
                {
                    "en": "Despite being warned, he continued.",
                    "ua": "Попри попередження, він продовжив."
                },
                {
                    "en": "Before being hired, she had to pass a test.",
                    "ua": "Перед тим як її найняли, вона мусила скласти тест."
                }
            ]
        },
        {
            "label": "Після remember \/ forget \/ deny",
            "color": "amber",
            "description": "Коли підмет є <strong>об'єктом дії<\/strong>:",
            "examples": [
                {
                    "en": "I remember being told about it.",
                    "ua": "Я пам'ятаю, що мені про це казали."
                },
                {
                    "en": "She denies being involved.",
                    "ua": "Вона заперечує свою причетність."
                },
                {
                    "en": "He will never forget being helped by her.",
                    "ua": "Він ніколи не забуде, як вона йому допомогла."
                }
            ]
        }
    ]
}

{
    "title": "3. Перфектний пасивний герундій (having been done)",
    "sections": [
        {
            "label": "Причина → наслідок",
            "color": "emerald",
            "description": "Для дій, що <strong>передували іншим<\/strong> і стали їхньою причиною:",
            "examples": [
                {
                    "en": "Having been warned, he was more careful.",
                    "ua": "Отримавши попередження, він був обережнішим."
                },
                {
                    "en": "Having been told the truth, she felt relieved.",
                    "ua": "Дізнавшись правду, вона відчула полегшення."
                },
                {
                    "en": "Having been rejected twice, he gave up.",
                    "ua": "Отримавши відмову двічі, він здався."
                }
            ]
        },
        {
            "label": "Формальний стиль",
            "color": "blue",
            "description": "Часто в <strong>академічному та офіційному<\/strong> письмі:",
            "examples": [
                {
                    "en": "Having been approved by the board, the project will begin.",
                    "ua": "Після схвалення радою проєкт розпочнеться."
                },
                {
                    "en": "Having been elected, she took office immediately.",
                    "ua": "Після обрання вона негайно обійняла посаду."
                },
                {
                    "en": "Having been tested, the product was released.",
                    "ua": "Після тестування продукт був випущений."
                }
            ]
        },
        {
            "label": "Після прийменників",
            "color": "rose",
            "description": "Для підкреслення <strong>попередньої дії<\/strong>:",
            "examples": [
                {
                    "en": "After having been informed, he took action.",
                    "ua": "Після того як його поінформували, він вжив заходів."
                },
                {
                    "en": "Despite having been warned, she ignored the advice.",
                    "ua": "Попри попередження, вона проігнорувала пораду."
                },
                {
                    "en": "On having been asked, he explained everything.",
                    "ua": "На запитання він усе пояснив."
                }
            ]
        }
    ]
}

{
    "title": "4. Слова та вирази з пасивним герундієм",
    "sections": [
        {
            "label": "Дієслова почуттів",
            "color": "emerald",
            "description": "<strong>like, love, hate, enjoy, dislike, prefer, avoid, mind, can't stand<\/strong>:",
            "examples": [
                {
                    "en": "I can't stand being ignored.",
                    "ua": "Я не виношу, коли мене ігнорують."
                },
                {
                    "en": "She avoids being seen by him.",
                    "ua": "Вона уникає того, щоб він її бачив."
                },
                {
                    "en": "They prefer being given clear instructions.",
                    "ua": "Вони віддають перевагу чітким інструкціям."
                }
            ]
        },
        {
            "label": "Дієслова пам'яті \/ мовлення",
            "color": "blue",
            "description": "<strong>remember, forget, deny, admit, recall, mention<\/strong>:",
            "examples": [
                {
                    "en": "He admitted being wrong.",
                    "ua": "Він визнав, що помилився."
                },
                {
                    "en": "She recalls being praised by her teacher.",
                    "ua": "Вона пригадує, як її хвалила вчителька."
                },
                {
                    "en": "He mentioned being offered a job.",
                    "ua": "Він згадав, що йому пропонували роботу."
                }
            ]
        },
        {
            "label": "Стійкі вирази",
            "color": "amber",
            "description": "<strong>be worth, be used to, look forward to, be afraid of<\/strong>:",
            "examples": [
                {
                    "en": "The book is worth being read.",
                    "ua": "Цю книгу варто прочитати."
                },
                {
                    "en": "She is used to being watched.",
                    "ua": "Вона звикла, що за нею спостерігають."
                },
                {
                    "en": "I'm afraid of being punished.",
                    "ua": "Я боюся, що мене покарають."
                }
            ]
        }
    ]
}

{
    "title": "5. Порівняння: being done vs having been done",
    "intro": "Коли використовувати простий чи перфектний пасивний герундій:",
    "rows": [
        {
            "en": "being done",
            "ua": "Одночасна дія або загальне твердження",
            "note": "She hates being interrupted. — Вона ненавидить, коли її перебивають."
        },
        {
            "en": "having been done",
            "ua": "Попередня (раніша) дія",
            "note": "Having been warned, he was careful. — Отримавши попередження, він був обережнішим."
        },
        {
            "en": "being done (прийменник)",
            "ua": "Процес \/ одночасність",
            "note": "Without being noticed, he left. — Непомітно він пішов."
        },
        {
            "en": "having been done (причина)",
            "ua": "Причинно-наслідковий зв'язок",
            "note": "Having been rejected, she tried again. — Отримавши відмову, вона спробувала знову."
        }
    ],
    "warning": "📌 Перфектний герундій підкреслює, що дія сталася РАНІШЕ за основну дію в реченні!"
}

{
    "title": "6. Порівняння: Active vs Passive Gerund",
    "intro": "Коли підмет виконує дію (active) чи зазнає дії (passive):",
    "rows": [
        {
            "en": "Active: He likes helping others.",
            "ua": "Йому подобається допомагати іншим.",
            "note": "Він (підмет) допомагає."
        },
        {
            "en": "Passive: He likes being helped.",
            "ua": "Йому подобається, коли йому допомагають.",
            "note": "Йому (підмету) допомагають."
        },
        {
            "en": "Active: I remember telling her.",
            "ua": "Я пам'ятаю, як сказав їй.",
            "note": "Я сказав."
        },
        {
            "en": "Passive: I remember being told.",
            "ua": "Я пам'ятаю, що мені сказали.",
            "note": "Мені сказали."
        }
    ],
    "warning": "📌 Якщо підмет є виконавцем дії — active gerund. Якщо підмет зазнає дії — passive gerund."
}

{
    "title": "7. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пропуск being у пасивному герундії.",
            "wrong": "She hates criticized.",
            "right": "✅ She hates being criticized."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Використання V1 замість V3.",
            "wrong": "He enjoys being praise.",
            "right": "✅ He enjoys being praised."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Плутання простого та перфектного.",
            "wrong": "Being warned yesterday, he was careful.",
            "right": "✅ Having been warned yesterday, he was careful."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Неправильний порядок слів у перфектному.",
            "wrong": "been having done",
            "right": "✅ having been done"
        }
    ]
}

{
    "title": "Passive Infinitive and Gerund",
    "items": [
        {
            "label": "Passive Infinitive — to be done / to have been done",
            "current": false
        },
        {
            "label": "Passive Gerund — being done / having been done",
            "current": true
        }
    ]
}

{
    "level": "A2",
    "intro": "У цій темі ти вивчиш <strong>Present Simple Passive<\/strong>: як утворювати ствердження, заперечення та питання у пасивному стані теперішнього часу.",
    "rules": [
        {
            "label": "Формула",
            "color": "emerald",
            "text": "<strong>am\/is\/are + V3<\/strong>:",
            "example": "The letter is written."
        },
        {
            "label": "Заперечення",
            "color": "rose",
            "text": "<strong>am\/is\/are + not + V3<\/strong>:",
            "example": "The letter is not written."
        },
        {
            "label": "Питання",
            "color": "blue",
            "text": "<strong>Am\/Is\/Are + S + V3?<\/strong>:",
            "example": "Is the letter written?"
        }
    ]
}

{
    "title": "1. Вибір am\/is\/are",
    "intro": "Дієслово <strong>be<\/strong> залежить від підмета:",
    "items": [
        {
            "label": "I",
            "title": "am",
            "subtitle": "I am paid monthly."
        },
        {
            "label": "He\/She\/It",
            "title": "is",
            "subtitle": "It is made in China."
        },
        {
            "label": "You\/We\/They",
            "title": "are",
            "subtitle": "They are invited to the party."
        },
        {
            "label": "Plural nouns",
            "title": "are",
            "subtitle": "Cars are produced here."
        }
    ]
}

{
    "title": "2. Стверджувальні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "emerald",
            "description": "Порядок: <strong>Subject + am\/is\/are + V3 (+ by agent)<\/strong>",
            "examples": [
                {
                    "en": "English is spoken in many countries.",
                    "ua": "Англійська розмовляється в багатьох країнах."
                },
                {
                    "en": "The rooms are cleaned every day.",
                    "ua": "Кімнати прибираються щодня."
                },
                {
                    "en": "I am paid at the end of each month.",
                    "ua": "Мені платять наприкінці кожного місяця."
                }
            ]
        },
        {
            "label": "Коли використовувати?",
            "color": "sky",
            "description": "Для <strong>регулярних дій<\/strong>, <strong>загальних фактів<\/strong> та <strong>звичок<\/strong>:",
            "examples": [
                {
                    "en": "Coffee is grown in Brazil.",
                    "ua": "Каву вирощують у Бразилії. (загальний факт)"
                },
                {
                    "en": "Newspapers are delivered every morning.",
                    "ua": "Газети доставляють щоранку. (регулярна дія)"
                },
                {
                    "en": "This road is used by many cars.",
                    "ua": "Цією дорогою користуються багато машин."
                }
            ]
        }
    ]
}

{
    "title": "3. Заперечні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "rose",
            "description": "Додаємо <strong>not<\/strong> після am\/is\/are: <strong>Subject + am\/is\/are + not + V3<\/strong>",
            "examples": [
                {
                    "en": "The door is not locked.",
                    "ua": "Двері не замкнені."
                },
                {
                    "en": "These cars are not made in Japan.",
                    "ua": "Ці машини не виробляються в Японії."
                },
                {
                    "en": "I am not invited to the meeting.",
                    "ua": "Мене не запросили на зустріч."
                }
            ]
        },
        {
            "label": "Скорочені форми",
            "color": "amber",
            "description": "У розмовній мові використовують <strong>isn't \/ aren't<\/strong>:",
            "examples": [
                {
                    "en": "The window isn't opened.",
                    "ua": "Вікно не відкрите."
                },
                {
                    "en": "The reports aren't finished yet.",
                    "ua": "Звіти ще не готові."
                }
            ],
            "note": "Форма <strong>am not<\/strong> не скорочується: I am not (I'm not)."
        }
    ]
}

{
    "title": "4. Питальні речення",
    "sections": [
        {
            "label": "Yes\/No питання",
            "color": "blue",
            "description": "<strong>Am\/Is\/Are<\/strong> виходить на перше місце: <strong>Am\/Is\/Are + Subject + V3?<\/strong>",
            "examples": [
                {
                    "en": "Is English spoken here?",
                    "ua": "Тут розмовляють англійською?"
                },
                {
                    "en": "Are the rooms cleaned daily?",
                    "ua": "Кімнати прибираються щодня?"
                },
                {
                    "en": "Am I included in the list?",
                    "ua": "Мене включено до списку?"
                }
            ]
        },
        {
            "label": "Wh-питання",
            "color": "sky",
            "description": "<strong>Wh-word + am\/is\/are + Subject + V3?<\/strong>",
            "examples": [
                {
                    "en": "Where is coffee grown?",
                    "ua": "Де вирощують каву?"
                },
                {
                    "en": "How often are the rooms cleaned?",
                    "ua": "Як часто прибираються кімнати?"
                },
                {
                    "en": "Why is this product so popular?",
                    "ua": "Чому цей продукт такий популярний?"
                }
            ]
        },
        {
            "label": "Короткі відповіді",
            "color": "amber",
            "description": "Відповіді з <strong>Yes\/No + am\/is\/are (not)<\/strong>:",
            "examples": [
                {
                    "en": "Is the letter written? — Yes, it is. \/ No, it isn't.",
                    "ua": "Лист написаний? — Так. \/ Ні."
                },
                {
                    "en": "Are they invited? — Yes, they are. \/ No, they aren't.",
                    "ua": "Їх запросили? — Так. \/ Ні."
                }
            ]
        }
    ]
}

{
    "title": "5. Active vs Passive: Present Simple",
    "intro": "Порівняння активного та пасивного стану:",
    "rows": [
        {
            "en": "Active: Tom writes letters every day.",
            "ua": "Том пише листи щодня.",
            "note": "→ Passive: Letters are written every day."
        },
        {
            "en": "Active: They clean the rooms daily.",
            "ua": "Вони прибирають кімнати щодня.",
            "note": "→ Passive: The rooms are cleaned daily."
        },
        {
            "en": "Active: People speak English here.",
            "ua": "Люди тут розмовляють англійською.",
            "note": "→ Passive: English is spoken here."
        }
    ],
    "warning": "📌 Маркери часу (every day, always, often) залишаються!"
}

{
    "title": "6. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Неправильний вибір is\/are.",
            "wrong": "The letters is sent every day.",
            "right": "✅ The letters are sent every day."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Пропуск be у питаннях.",
            "wrong": "The room cleaned daily?",
            "right": "✅ Is the room cleaned daily?"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Використання V1 замість V3.",
            "wrong": "English is speak here.",
            "right": "✅ English is spoken here."
        }
    ]
}

{
    "title": "Passive in Tenses",
    "items": [
        {
            "label": "Present Simple Passive — Теперішній простий пасив",
            "current": true
        },
        {
            "label": "Present Continuous Passive — Теперішній тривалий пасив",
            "current": false
        },
        {
            "label": "Present Perfect Passive — Теперішній доконаний пасив",
            "current": false
        },
        {
            "label": "Past Simple Passive — Минулий простий пасив",
            "current": false
        },
        {
            "label": "Past Continuous Passive — Минулий тривалий пасив",
            "current": false
        },
        {
            "label": "Past Perfect Passive — Минулий доконаний пасив",
            "current": false
        },
        {
            "label": "Future Simple Passive — Майбутній простий пасив",
            "current": false
        },
        {
            "label": "Future Continuous Passive — Майбутній тривалий пасив",
            "current": false
        },
        {
            "label": "Future Perfect Passive — Майбутній доконаний пасив",
            "current": false
        }
    ]
}

{
    "level": "A2",
    "intro": "У цій темі ти вивчиш <strong>Past Simple Passive<\/strong>: як утворювати ствердження, заперечення та питання у пасивному стані минулого часу.",
    "rules": [
        {
            "label": "Формула",
            "color": "emerald",
            "text": "<strong>was\/were + V3<\/strong>:",
            "example": "The house was built in 1990."
        },
        {
            "label": "Заперечення",
            "color": "rose",
            "text": "<strong>was\/were + not + V3<\/strong>:",
            "example": "The letter was not sent."
        },
        {
            "label": "Питання",
            "color": "blue",
            "text": "<strong>Was\/Were + S + V3?<\/strong>:",
            "example": "Was the house built in 1990?"
        }
    ]
}

{
    "title": "1. Вибір was\/were",
    "intro": "Дієслово <strong>be<\/strong> в минулому часі:",
    "items": [
        {
            "label": "I\/He\/She\/It",
            "title": "was",
            "subtitle": "I was invited. The house was built."
        },
        {
            "label": "You\/We\/They",
            "title": "were",
            "subtitle": "You were told. They were arrested."
        },
        {
